/**
 * Every NBA team in every season from 1983-84 through 2025-26, with its full roster (the 13 players with the
 * most minutes), generated by scripts/rosters/build.py. Hand-rated players keep their ratings; everyone else is
 * rated from their real season stats. Parsed on first use: only the modes that need history pay for it.
 */
import { registerContracts } from '../engine/cap';
import type { ContractType } from './contracts';
import type { TeamSeason } from '../engine/types';
import { season } from './history/build';
import { FULL_SEASONS } from './history/full';

const DEAL: Record<string, ContractType> = { S: 'supermax', M: 'max', R: 'rookie', T: 'twoWay', N: 'min', D: 'standard', E: 'est' };

let cache: TeamSeason[] | null = null;

export function fullSeasons(): TeamSeason[] {
  if (!cache) {
    const seen = new Set<string>();
    cache = Object.entries(FULL_SEASONS).flatMap(([y, teams]) =>
      teams.map(([franchise, city, name, colors, roster]) => {
        // Each line ends with his real contract that season: "|$12.3:M" (game $M and deal type).
        const deals: ([number, ContractType] | null)[] = [];
        const lines = roster.split('\n').map((line) => {
          const m = /\|\$([\d.]+):([SMRTNDE])$/.exec(line);
          deals.push(m ? [Number(m[1]), DEAL[m[2]]] : null);
          return m ? line.slice(0, m.index) : line;
        });
        const t = season(franchise, city, name, Number(y), colors, lines.join('\n'));
        // Two different players with the same name in one season (the two Eddie Johnsons): the second gets his
        // team in his id, so every player-season has its own.
        const players = t.players.map((p) => (seen.has(p.id) ? { ...p, id: `${p.id}-${franchise}` } : (seen.add(p.id), p)));
        registerContracts(players.flatMap((p, i) => (deals[i] ? [[p.id, deals[i]!] as [string, [number, ContractType]]] : [])));
        return { ...t, players };
      }));
  }
  return cache;
}

/** The seasons covered in full (end years). */
export const FULL_YEARS = Object.keys(FULL_SEASONS).map(Number);
